1	#!/bin/sh
2	# usage: find-transcript.sh <workspace-path> <opening-prompt-substring>
3	set -eu
4	slug=$(printf '%s' "$1" | sed 's/[^A-Za-z0-9-]/-/g')
5	dir="$HOME/.claude/projects/$slug"
6	[ -d "$dir" ] || { printf 'no transcript directory: %s\n' "$dir" >&2; exit 1; }
7	newest_sessions() { ls -t "$dir"/*.jsonl 2>/dev/null | head -10; }
8	newest_subagents() { ls -t "$dir"/*/subagents/*.jsonl 2>/dev/null | head -10; }
9	match=$({ newest_sessions; newest_subagents; } | while IFS= read -r f; do
10	  grep -m1 '"type":"user"' "$f" | grep -qF -- "$2" && { printf '%s\n' "$f"; break; }
11	done)
12	[ -n "$match" ] || { printf 'no transcript in %s matched the opening prompt\n' "$dir" >&2; exit 1; }
13	printf '%s\n' "$match"
14

